import{_ as i,l as o,o as e,c as l,v as r,p as c,x as t,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"投递语义","description":"","frontmatter":{"title":"投递语义","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/delivery-semantics.md","filePath":"cs/delivery-semantics.md","lastUpdated":1789023840000}'),h={name:"cs/delivery-semantics.md"};function m(_,a,k,E,f,u){const s=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="投递语义" tabindex="-1">投递语义 <a class="header-anchor" href="#投递语义" aria-label="Permalink to &quot;投递语义&quot;">​</a></h1><div class="epigraph"><p>消息队列保证的是 broker 与消费者之间的投递次数，不是业务效果。至少一次投递加非幂等处理，效果是至少两次。</p><footer>—— 据 ISO/OSI 与分布式教材中的可靠广播分类；Kreps 等对日志投递的实践整理</footer></div><p>上一课<a href="/cs/rpc-semantics">RPC</a>谈过程执行次数。缺口是<strong>异步消息</strong>：生产者、队列、消费者三方，ack 点不同，词还是至少/至多/恰好，指称对象却换成「消息从队列消失几次、被处理几次」。本课钉投递，不重写桩。后课幂等键把效果钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>至少一次投递：消费者可能收到重复（崩溃在 ack 前）。至多一次：可能丢（ack 先于处理）。恰好一次投递：broker 与消费者协议让每条消息对消费者的<strong>可见处理</strong>一次——通常用事务消费或幂等生产者 id + 去重表，底层仍常是至少一次运输。</p><p>缺口：把 Kafka <code>acks=all</code> 当恰好一次业务。那是生产者到日志的持久，不是下游两次副作用。EOS（ exactly-once semantics）是特定系统里「读-处理-写」事务的品牌，规格要读论文与文档的限定范围，本课只警告品牌 ≠ 全局恰好一次。</p><p><span class="marginnote">可靠广播、FIFO 广播、因果广播是另一轴（排序），不要和次数轴混成一个词。Birman 的 Isis 谈排序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 ack 点：处理前 ack ⇒ 可丢；处理后 ack ⇒ 可重复。恰好一次效果：至少一次投递 + 幂等处理，或两者包进同一事务（消费位移与副作用同提交）。</p>',9)),(e(),c(p,null,{default:t(()=>[d(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22%E7%94%9F%E4%BA%A7%E8%80%85%22%5D%20--%3E%20Q%5B%22%E9%98%9F%E5%88%97%20%2F%20%E6%97%A5%E5%BF%97%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E6%B6%88%E8%B4%B9%E8%80%85%22%5D%0A%20%20C%20--%3E%20ACK%5B%22ack%20%E4%BD%8D%E7%A7%BB%22%5D%0A%20%20ACK%20--%3E%20DUP%7B%22ack%20%E4%B8%8E%E5%89%AF%E4%BD%9C%E7%94%A8%E6%AC%A1%E5%BA%8F%22%7D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>死信、重试次数上限是工程，把无限至少一次切成有界。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>重复来源：生产者重试未收到 broker ack（要生产者幂等键）、消费者重平衡时位移回退、网络重传。丢失来源：位移先提交、broker 未刷盘就 ack、TTL 丢弃。与<a href="/cs/replicated-state-machine">RSM</a>：日志提交是多数派持久，投给消费者仍是另一通道。</p><p>本课不写 Kafka 事务协议全文（后课日志课抓副本与位移）。也不把邮件 SMTP 的重试当队列定理。</p><p>与 RPC 对照：同步 RPC 的重试对应生产者重试；服务端 xid 表对应消费者去重表。换了拓扑，代数一样。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Saga 补偿流。不把 MQTT QoS 0/1/2 当新理论，只点名它们是同一分类。后课默认：队列广告词先翻译成 ack 点；效果一次靠幂等或事务。下一课专讲幂等键。</p><p>次数保证有主语。主语是 broker 还是业务表，答案不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>投递次数 ≠ 业务效果次数。</li><li>处理后 ack 可重复；处理前 ack 可丢失。</li><li>恰好一次效果 = 至少一次运输 + 幂等或事务去重。</li><li>出处：可靠通信分类；日志系统实践（Kreps 等）。</li></ul>',10))])}const T=i(h,[["render",m]]);export{B as __pageData,T as default};
